// Shared lookup for manually curated Heureka CPC (max cena za preklik) overrides, used by every
// transform-*.js to emit <HEUREKA_CPC> for products with a known EAN in the overrides file.
//
// Unlike heureka-price-targets.js, data/heureka-reports/cpc-overrides.json is NOT generated by
// the daily report run — it's a small, hand-picked test list (EAN -> { cpc, ... }) built from a
// sortiment report + a performance report reviewed together (see reports/ for the analysis this
// came from, 2026-08-18: Šport a outdoor bidding-position gap). Add/remove/adjust entries by hand
// as tests conclude; there is no automatic generator for this file (yet).
//
// KILL SWITCH: same pattern as heureka-price-targets.js — wired into every transform-*.js but
// held INACTIVE until someone explicitly sets HEUREKA_CPC_OVERRIDE=1 (e.g. as a step env var in
// the supplier sync workflows). Until then heurekaCpcFor() always returns undefined and no
// <HEUREKA_CPC> tag is emitted, regardless of what's in cpc-overrides.json.
//
// If there's no overrides file yet, or no entry for a given EAN, no tag is emitted — this module
// never invents a CPC bid.

const fs = require('fs');
const path = require('path');

const OVERRIDES_PATH = path.join(__dirname, '..', 'data', 'heureka-reports', 'cpc-overrides.json');
const OVERRIDE_ENABLED = process.env.HEUREKA_CPC_OVERRIDE === '1';

let cache;
function loadOverrides() {
  if (cache !== undefined) return cache;
  if (!fs.existsSync(OVERRIDES_PATH)) { cache = {}; return cache; }
  try {
    cache = JSON.parse(fs.readFileSync(OVERRIDES_PATH, 'utf-8'));
  } catch (e) {
    console.error(`Warning: could not parse ${OVERRIDES_PATH}, ignoring Heureka CPC overrides: ${e.message}`);
    cache = {};
  }
  return cache;
}

// Returns the override CPC (a number, e.g. 0.35) for this EAN, or undefined when the kill switch
// is off, there's no override file, or no entry matches this EAN.
function heurekaCpcFor(ean) {
  if (!OVERRIDE_ENABLED) return undefined;
  if (!ean) return undefined;
  const entry = loadOverrides()[ean];
  if (!entry || !Number.isFinite(entry.cpc)) return undefined;
  return entry.cpc;
}

module.exports = { heurekaCpcFor, loadOverrides, OVERRIDES_PATH, OVERRIDE_ENABLED };
